<script setup>
import {Head,Link,router} from '@inertiajs/vue3';import AdminLayout from '../Components/AdminLayout.vue';import {Plus,Pencil,Trash2} from '@lucide/vue';import Swal from 'sweetalert2';
const props=defineProps({type:String,records:Array});const label=props.type==='coupon'?'Coupon':'Gift card';const endpoint=props.type==='coupon'?'/admin/coupons':'/admin/gift-cards';
async function remove(record){const result=await Swal.fire({title:'Delete '+label.toLowerCase()+'?',text:record.code+' will no longer be available at checkout.',icon:'warning',showCancelButton:true,confirmButtonText:'Delete',confirmButtonColor:'#a43b4f'});if(result.isConfirmed)router.delete(endpoint+'/'+record.id,{preserveScroll:true});}
</script>
<template><Head :title="label+'s'"/><AdminLayout :title="label+'s'"><div class="page-heading"><div><span class="eyebrow">CHECKOUT DISCOUNTS</span><h1>{{ label }}s</h1><p>Manage your saved {{ label.toLowerCase() }} codes.</p></div><Link :href="endpoint+'/create'" class="btn primary"><Plus :size="16"/>Create {{ label.toLowerCase() }}</Link></div><section class="panel discount-list"><div style="overflow:auto"><table><thead><tr><th>Name</th><th>Code</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="record in records" :key="record.id"><td>{{ record.name }}</td><td><strong>{{ record.code }}</strong></td><td>৳{{ Number(record.amount).toLocaleString() }}</td><td><span :class="record.status?'active':'inactive'">{{ record.status?'Active':'Inactive' }}</span></td><td><div style="display:flex;gap:8px"><Link :href="endpoint+'/'+record.id+'/edit'" class="btn secondary" :aria-label="'Edit '+record.code"><Pencil :size="15"/>Edit</Link><button class="btn secondary" type="button" :aria-label="'Delete '+record.code" @click="remove(record)"><Trash2 :size="15"/>Delete</button></div></td></tr><tr v-if="!records.length"><td colspan="5" style="text-align:center;padding:40px">No codes yet. Click Create {{ label.toLowerCase() }} to add one.</td></tr></tbody></table></div></section></AdminLayout></template>
<style scoped>.discount-editor,.discount-list{padding:24px;margin-bottom:22px;border-radius:16px}.discount-editor h2{display:flex;gap:10px;font-weight:700;margin-bottom:20px}.discount-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.discount-fields label{display:flex;flex-direction:column;gap:8px;font-size:12px;font-weight:600}.discount-fields input,.discount-fields select{padding:11px;border:1px solid #dce5df;border-radius:8px;background:white;font:inherit}.discount-fields small{color:#ae3549}.discount-actions{display:flex;gap:10px;margin-top:18px}.discount-hint{font-size:12px;color:#75847c;line-height:1.7;margin-top:16px}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:15px 12px;border-bottom:1px solid #edf0ee;white-space:nowrap}td button{padding:7px;display:inline-flex;color:#577465}.active,.inactive{padding:5px 9px;border-radius:6px;background:#e8f5ed;color:#267752}.inactive{background:#f4ebee;color:#a54459}@media(max-width:900px){.discount-fields{grid-template-columns:1fr 1fr}}@media(max-width:500px){.discount-fields{grid-template-columns:1fr}.discount-editor,.discount-list{padding:18px}}</style>
